-- ============================================
-- LUMA — Thème 12 : LONG 3/3 x4 — Un débat historique animé avec un guide
-- ============================================


update scenarios set content = '{"characters": {"guide": "le guide"}, "start_node": "n1", "nodes": {"n1": {"speaker": "guide", "text": "This exhibit covers a controversial colonial expedition. Historians still debate its true legacy today.", "text_fr": "Cette exposition couvre une expédition coloniale controversée. Les historiens débattent encore de son vrai héritage aujourd''hui.", "choices": [{"text": "What are the main perspectives historians disagree on?", "text_fr": "Quelles sont les principales perspectives sur lesquelles les historiens sont en désaccord ?", "next": "n2"}, {"text": "I''d love to hear your personal take on this, if you''re comfortable sharing.", "text_fr": "J''aimerais entendre votre avis personnel là-dessus, si vous êtes à l''aise de le partager.", "next": "n2b"}]}, "n2": {"speaker": "guide", "text": "Some argue it brought technological progress; others emphasize the devastating human cost.", "text_fr": "Certains soutiennent que ça a apporté un progrès technologique ; d''autres soulignent le coût humain dévastateur.", "choices": [{"text": "Can both perspectives hold truth simultaneously, do you think?", "text_fr": "Les deux perspectives peuvent-elles contenir de la vérité simultanément, à votre avis ?", "next": "n3"}, {"text": "Which perspective do you think is more historically accurate?", "text_fr": "Quelle perspective pensez-vous être la plus historiquement exacte ?", "next": "n3"}]}, "n2b": {"speaker": "guide", "text": "As a guide, I try to stay neutral, but I do think we can''t ignore the human suffering involved.", "text_fr": "En tant que guide, j''essaie de rester neutre, mais je pense qu''on peut pas ignorer la souffrance humaine impliquée.", "choices": [{"text": "I respect that you center human impact in the discussion.", "text_fr": "Je respecte que vous centriez l''impact humain dans la discussion.", "next": "n3"}]}, "n3": {"speaker": "guide", "text": "That''s the complexity of history — progress and suffering often intertwined, uncomfortably so.", "text_fr": "C''est la complexité de l''histoire — progrès et souffrance souvent entrelacés, de façon inconfortable.", "choices": [{"text": "I think it''s important we don''t sanitize history to make it more comfortable.", "text_fr": "Je pense qu''il est important de pas édulcorer l''histoire pour la rendre plus confortable.", "next": "n4"}, {"text": "But shouldn''t we also recognize genuine achievements, even from difficult periods?", "text_fr": "Mais ne devrait-on pas aussi reconnaître les vraies réalisations, même de périodes difficiles ?", "next": "n4"}]}, "n4": {"speaker": "guide", "text": "Both are true, I''d argue. The challenge is holding complexity without erasing anyone''s experience.", "text_fr": "Les deux sont vrais, je dirais. Le défi est de garder la complexité sans effacer l''expérience de personne.", "choices": [{"text": "That''s a nuanced way to approach difficult history. How do museums typically handle this balance?", "text_fr": "C''est une façon nuancée d''aborder l''histoire difficile. Comment les musées gèrent-ils généralement cet équilibre ?", "next": "n5"}]}, "n5": {"speaker": "guide", "text": "It varies greatly. Some museums lean heavily into critique, others into celebration — we try for balance.", "text_fr": "Ça varie énormément. Certains musées penchent fortement vers la critique, d''autres vers la célébration — on essaie l''équilibre.", "choices": [{"text": "Do you think that balance is always achievable, or sometimes one side needs more emphasis?", "text_fr": "Pensez-vous que cet équilibre est toujours réalisable, ou parfois un côté a besoin de plus d''accent ?", "next": "n6"}]}, "n6": {"speaker": "guide", "text": "Honestly? Sometimes emphasis matters more than balance, especially when correcting historical erasure.", "text_fr": "Honnêtement ? Parfois l''accent compte plus que l''équilibre, surtout quand on corrige un effacement historique.", "choices": [{"text": "That''s a compelling point — giving voice to previously silenced perspectives.", "text_fr": "C''est un point convaincant — donner une voix aux perspectives précédemment réduites au silence.", "next": "n7"}, {"text": "I see your point, though I still think presenting multiple views helps visitors think critically.", "text_fr": "Je vois votre point, même si je pense encore que présenter plusieurs points de vue aide les visiteurs à penser de façon critique.", "next": "n7"}]}, "n7": {"speaker": "guide", "text": "Both approaches have merit, honestly. This exhibit actually tries to do a bit of both.", "text_fr": "Les deux approches ont du mérite, honnêtement. Cette exposition essaie en fait de faire un peu des deux.", "choices": [{"text": "I noticed that — the personal testimonies alongside the broader historical context.", "text_fr": "J''ai remarqué ça — les témoignages personnels aux côtés du contexte historique plus large.", "next": "n8"}]}, "n8": {"speaker": "guide", "text": "Exactly. We wanted visitors to feel the human stakes, not just absorb dates and facts.", "text_fr": "Exactement. On voulait que les visiteurs ressentent les enjeux humains, pas juste absorber des dates et des faits.", "choices": [{"text": "That approach really succeeded for me today — this exhibit felt genuinely thought-provoking.", "text_fr": "Cette approche a vraiment réussi pour moi aujourd''hui — cette exposition m''a semblé vraiment stimulante.", "next": "n9"}]}, "n9": {"speaker": "guide", "text": "That means a lot to hear. Debates like this one are exactly why I love this job.", "text_fr": "Ça compte beaucoup à entendre. Des débats comme celui-ci sont exactement pourquoi j''adore ce travail.", "choices": [{"text": "Thank you for engaging so thoughtfully with these difficult questions today.", "text_fr": "Merci d''avoir abordé ces questions difficiles avec autant de réflexion aujourd''hui.", "next": "end_debated"}]}, "end_debated": {"speaker": "guide", "text": "Thank you for pushing the conversation further — that''s exactly what history deserves.", "text_fr": "Merci d''avoir poussé la conversation plus loin — c''est exactement ce que l''histoire mérite.", "end": true, "ending_label": "Débat historique nuancé et enrichissant 🏛️💭"}}}'::jsonb, is_playable = true
where title = 'Un débat historique animé avec un guide'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));
